import React, { useState } from 'react';

export default function RegistrationForm() {
  const [step, setStep] = useState(1); 
  const [error, setError] = useState({});
  const [form, setForm] = useState({
    // 🧍‍♂️ Basic Personal Information
    fullName: '',
    email: '',
    phone: '',
    dob: '',
    gender: '',
    location: '',

    // 🩺 Health & Lifestyle Information
    height: '',
    weight: '',
    fitnessLevel: '',
    medicalConditions: '',
    allergies: '',
    sleep: '',
    habits: '',

    // 🎯 Goals & Preferences
    goals: '',
    coachingStyle: '',
    workoutPreferences: '',
    dietaryPreferences: '',
    timeAvailability: ''
  });


  const Validate = () => {
    let e = {};

    if(step === 1){
        if(!form.fullName) e.fullName = "Full Name is required";
        if(!form.email) e.email = "Email is required";
        if(!form.phone) e.phone = "Phone Number is required";
        if(!form.dob) e.dob = "Date of Birth is required";
        if(!form.gender) e.gender = "Gender is required";
        if(!form.location) e.location = "Location is required";
    }

    if(step === 2){
        if(!form.height) e.height = "Height is required";
        if(!form.weight) e.weight = "Weight is required";
        if(!form.fitnessLevel) e.fitnessLevel = "Current Fitness Level is required";
        if(!form.medicalConditions) e.medicalConditions = "Medical Conditions is required";
        if(!form.sleep) e.sleep = "Sleep Patterns is required";
    }

    if(step === 3){
        if(!form.goals) e.goals = "Health Goals is required";
        if(!form.coachingStyle) e.coachingStyle = "Preferred Coaching Style is required";
        if(!form.timeAvailability) e.timeAvailability = "Time Availability is required";
    }

    setError(e);

    return ob
  } 

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const nextStep = () => setStep(step + 1);
  const prevStep = () => setStep(step - 1);

  const handleSubmit = (e) => {
    e.preventDefault();
    console.log("Form submitted:", form);
    alert("Registration successful!");
  };

  return (
    <div className="container mt-5" style={{ marginBottom: '100px' }}>
      <div className="card shadow-sm p-4" style={{ maxWidth: "600px", margin: "auto" }}>
        <h3 className="text-center mb-4">Health Coach Registration</h3>

        <form onSubmit={handleSubmit}>
          {/* Step 1: Basic Info */}
          {step === 1 && (
            <>
              <h5>🧍‍♂️ Basic Personal Information</h5>
              <div className="mb-3">
                <label className="form-label">Full Name</label>
                <input type="text" name="fullName" value={form.fullName} onChange={handleChange} className="form-control" required />
              </div>
              <div className="mb-3">
                <label className="form-label">Email</label>
                <input type="email" name="email" value={form.email} onChange={handleChange} className="form-control" required />
              </div>
              <div className="mb-3">
                <label className="form-label">Phone Number</label>
                <input type="text" name="phone" value={form.phone} onChange={handleChange} className="form-control" required />
              </div>
              <div className="mb-3">
                <label className="form-label">Date of Birth</label>
                <input type="date" name="dob" value={form.dob} onChange={handleChange} className="form-control" required />
              </div>
              <div className="mb-3">
                <label className="form-label">Gender</label>
                <select name="gender" value={form.gender} onChange={handleChange} className="form-control" required>
                  <option value="">Select</option>
                  <option>Male</option>
                  <option>Female</option>
                  <option>Other</option>
                </select>
              </div>
              <div className="mb-3">
                <label className="form-label">Location / Time Zone</label>
                <input type="text" name="location" value={form.location} onChange={handleChange} className="form-control" required />
              </div>
              <button type="button" className="btn btn-primary w-100" onClick={nextStep}>Next</button>
            </>
          )}

          {/* Step 2: Health & Lifestyle */}
          {step === 2 && (
            <>
              <h5>🩺 Health & Lifestyle Information</h5>
              <div className="mb-3">
                <label className="form-label">Height (cm)</label>
                <input type="number" name="height" value={form.height} onChange={handleChange} className="form-control" required />
              </div>
              <div className="mb-3">
                <label className="form-label">Weight (kg)</label>
                <input type="number" name="weight" value={form.weight} onChange={handleChange} className="form-control" required />
              </div>
              <div className="mb-3">
                <label className="form-label">Current Fitness Level</label>
                <input type="text" name="fitnessLevel" value={form.fitnessLevel} onChange={handleChange} className="form-control" required />
              </div>
              <div className="mb-3">
                <label className="form-label">Medical Conditions</label>
                <input type="text" name="medicalConditions" value={form.medicalConditions} onChange={handleChange} className="form-control" />
              </div>
              <div className="mb-3">
                <label className="form-label">Allergies / Dietary Restrictions</label>
                <input type="text" name="allergies" value={form.allergies} onChange={handleChange} className="form-control" />
              </div>
              <div className="mb-3">
                <label className="form-label">Sleep Patterns</label>
                <input type="text" name="sleep" value={form.sleep} onChange={handleChange} className="form-control" />
              </div>
              <div className="mb-3">
                <label className="form-label">Smoking / Alcohol Habits</label>
                <input type="text" name="habits" value={form.habits} onChange={handleChange} className="form-control" />
              </div>
              <div className="d-flex justify-content-between">
                <button type="button" className="btn btn-secondary" onClick={prevStep}>Back</button>
                <button type="button" className="btn btn-primary" onClick={nextStep}>Next</button>
              </div>
            </>
          )}

          {/* Step 3: Goals & Preferences */}
          {step === 3 && (
            <>
              <h5>🎯 Goals & Preferences</h5>
              <div className="mb-3">
                <label className="form-label">Health Goals</label>
                <input type="text" name="goals" value={form.goals} onChange={handleChange} className="form-control" required />
              </div>
              <div className="mb-3">
                <label className="form-label">Preferred Coaching Style</label>
                <input type="text" name="coachingStyle" value={form.coachingStyle} onChange={handleChange} className="form-control" />
              </div>
              <div className="mb-3">
                <label className="form-label">Workout Preferences</label>
                <input type="text" name="workoutPreferences" value={form.workoutPreferences} onChange={handleChange} className="form-control" />
              </div>
              <div className="mb-3">
                <label className="form-label">Dietary Preferences</label>
                <input type="text" name="dietaryPreferences" value={form.dietaryPreferences} onChange={handleChange} className="form-control" />
              </div>
              <div className="mb-3">
                <label className="form-label">Time Availability</label>
                <input type="text" name="timeAvailability" value={form.timeAvailability} onChange={handleChange} className="form-control" />
              </div>
              <div className="d-flex justify-content-between">
                <button type="button" className="btn btn-secondary" onClick={prevStep}>Back</button>
                <button type="submit" className="btn btn-success">Submit</button>
              </div>
            </>
          )}
        </form>
      </div>
    </div>
  );
}
